interface Person {
  name: string;
  age: number;
  email?: string;
}

function greet(person: Person): string {
  if (person.email) {
    return `Hello ${person.name}, email: ${person.email}`;
  }
  return `Hello ${person.name}`;
}

const alice: Person = { name: 'Alice', age: 30 };
const bob: Person = { name: 'Bob', age: 25, email: 'bob@test.com' };

console.log(greet(alice));
console.log(greet(bob));
